//! Constructing a document (`new WP_Theme_JSON( $data, $origin )`) and the spacing sizes it pre-generates; every
//! expected value was produced by WordPress 7.1.5.
//!
//! Generated by `.superpowers/gen_construct.py`; edit the generator, not the cases.

mod support;

use speedyspec_hooks::Value;
use speedyspec_wp_theme_json::presets::spacing::{compute_spacing_sizes, merge_spacing_sizes};
use std::rc::Rc;

use speedyspec_wp_theme_json::{
    MemoryBlockMetadata, NoTranslation, RecordedDiagnostics, ThemeJsonCodec, ThemeJsonDeps,
    construct,
};
use speedyspec_wp_theme_json_contracts::model::ThemeJson;
use speedyspec_wp_theme_json_contracts::ports::{RegisteredBlock, TextFunctions};
use support::{assert_php_eq, json};

/// `sanitize_title_with_dashes` on the plain ASCII units these cases use: lower-cased.
struct LowerText;

impl TextFunctions for LowerText {
    fn sanitize_title(&self, s: &[u8]) -> Vec<u8> {
        s.to_ascii_lowercase()
    }
    fn sanitize_html_class(&self, s: &[u8]) -> Vec<u8> {
        s.to_vec()
    }
    fn esc_html(&self, s: &[u8]) -> Vec<u8> {
        s.to_vec()
    }
    fn esc_attr(&self, s: &[u8]) -> Vec<u8> {
        s.to_vec()
    }
}

fn blocks(list: &[(&str, &[&str])]) -> MemoryBlockMetadata {
    let blocks = MemoryBlockMetadata::new();
    for (name, styles) in list {
        blocks.register(RegisteredBlock {
            name: (*name).to_owned(),
            selectors: Value::Null,
            supports: Value::Null,
            style_names: styles.iter().map(|s| (*s).to_owned()).collect(),
        });
    }
    blocks
}

fn deps(blocks: MemoryBlockMetadata) -> ThemeJsonDeps {
    ThemeJsonDeps {
        blocks: Rc::new(blocks),
        text: Rc::new(LowerText),
        gettext: Rc::new(NoTranslation),
        diagnostics: Rc::new(RecordedDiagnostics::default()),
    }
}

fn raw(doc: ThemeJson) -> Value {
    ThemeJsonCodec::encode(&doc)
}

#[test]
fn presets_keyed_by_origin() {
    let actual = raw(construct(
        json(
            r##"{"version":3,"settings":{"color":{"palette":[{"slug":"red","color":"#f00","name":"Red"}]},"blocks":{"core/group":{"color":{"palette":[{"slug":"red","color":"#f00","name":"Red"}],"gradients":[]}}}}}"##,
        ),
        b"theme",
        &deps(blocks(&[("core/group", &["a"]), ("core/paragraph", &[])])),
    ));
    assert_php_eq(
        &actual,
        &json(
            r##"{"settings":{"blocks":{"core/group":{"color":{"gradients":{"theme":[]},"palette":{"theme":[{"color":"#f00","name":"Red","slug":"red"}]}}}},"color":{"palette":{"theme":[{"color":"#f00","name":"Red","slug":"red"}]}}},"version":3}"##,
        ),
    );
}

